@php($statusLabel = ['active' => 'Aktif', 'suspended' => 'Ditangguhkan', 'inactive' => 'Tidak aktif'][$card['member_status']] ?? ucfirst((string) $card['member_status']))
<td class="slot"><div class="card"><div class="top"><table class="brand"><tr><td class="mark"><div class="mark-circle">BM</div></td><td class="school">SMK BINA MANDIRI<small>PERPUSTAKAAN SEKOLAH</small></td><td class="badge-cell"><span class="badge">Kartu Anggota</span></td></tr></table></div><table class="body"><tr><td class="photo-cell">@if($card['photo_image'])<img class="photo" src="{{ $card['photo_image'] }}" alt="Foto">@else<div class="initials">{{ $initials ?: 'BM' }}</div>@endif</td><td class="info"><div class="name">{{ $card['name'] }}</div><div class="type">{{ $card['member_type'] === 'student' ? 'Siswa' : 'Staf' }}</div><table class="details"><tr><td class="label">NIS/NIP</td><td class="value">{{ $card['nis_nip'] ?: '-' }}</td></tr><tr><td class="label">No. anggota</td><td class="value">{{ $card['member_number'] ?: '-' }}</td></tr><tr><td class="label">Kelas/Jabatan</td><td class="value">{{ $card['class_name'] ?: '-' }}</td></tr>@if($card['major'])<tr><td class="label">Jurusan</td><td class="value">{{ $card['major'] }}</td></tr>@endif @if($card['academic_year'])<tr><td class="label">Tahun ajaran</td><td class="value">{{ $card['academic_year'] }}</td></tr>@endif</table></td><td class="qr-cell"><img class="qr" src="{{ $card['qr_image'] }}" alt="QR"><div class="scan">Pindai untuk identifikasi</div><span class="status {{ $card['member_status'] }}">{{ $statusLabel }}</span></td></tr></table><div class="bottom">KARTU INI MILIK PERPUSTAKAAN SMK BINA MANDIRI</div></div></td>
@endforeach @if($row->count() === 1)<td class="slot"></td>@endif</tr>
@endforeach
</table></div>
